H('564.d.3.B',4,"Corn, beans, and squash were staple crops of many Native American peoples, so they are:","indigenous to the Americas",["native to Europe only","unknown in North America","manufactured foods"],"Three Sisters.")
H('564.d.3.C',3,"A dish that balances sweet, sour, salty, and bitter tastes offers a pleasing:","flavor",["noise","weight","tax"],"Flavor.")
H('564.d.3.C',4,"Plating a creamy soup with a crunchy garnish adds contrast in:","texture",["weather","rent","tax"],"Texture.")
H('564.d.4.A',3,"Shutting off the tap and fixing leaky faucets helps a kitchen conserve:","water",["menus","tips","time cards"],"Conserve water.")
H('564.d.4.A',4,"Turning off idle ovens and using efficient fryers helps a kitchen conserve:","energy",["menus","tips","time cards"],"Conserve energy.")
H('564.d.4.B',3,"Sending food scraps to a compost bin instead of the trash is a way to reduce kitchen:","waste",["rent","menus","tips"],"Waste.")
H('564.d.4.B',4,"Weighing and tracking what is thrown out helps a kitchen see where it can cut:","waste",["rent","menus","tips"],"Track waste.")
H('564.d.4.C',3,"Buying seasonal produce from nearby farms is a sustainable food:","practice",["penalty","rumor","tax"],"Sustainable.")
H('564.d.4.C',4,"Choosing seafood that is caught or farmed in ways that protect ocean life supports:","sustainability",["inflation","waste","overfishing"],"Seafood.")
H('564.d.5.A',3,"Beef is graded by quality, and the top USDA quality grade is:","Prime",["Choice","Select","Standard"],"Grades.")
H('564.d.5.A',4,"The round USDA stamp on a carcass tells buyers that the meat was inspected and passed as safe and:","wholesome",["colorful","cheap","salted"],"Inspection.")
