H('564.d.5.C',4,"Removing the bones from a chicken breast is called:","deboning",["dicing","dredging","dusting"],"Deboning.")
H('564.d.5.D',3,"When buying meat, a chef compares price, yield, and the:","quality grade",["color of the box","driver's name","truck size"],"Purchasing.")
H('564.d.5.D',4,"Meat arriving at a temperature above 41 degrees F should be:","rejected",["accepted","refrozen","cooked later"],"Receiving meat.")
