H('564.d.5.E',4,"Tough cuts from the chuck are best cooked slowly with moist heat, such as:","braising",["broiling","grilling","pan-frying"],"Tough cuts.")
H('564.d.5.F',3,"The minimum safe internal temperature for poultry is:","165 degrees F",["145 degrees F","135 degrees F","155 degrees F"],"Poultry.")
H('564.d.5.F',4,"The minimum safe internal temperature for whole cuts of pork is:","145 degrees F",["125 degrees F","165 degrees F","185 degrees F"],"Pork.")
H('564.d.6.A',3,"Salmon, trout, and cod are classified as fin fish, while shrimp, crabs, and oysters are:","shellfish",["poultry","game","grains"],"Classification.")
